import { CustomPlaceTag } from '../../../shared/types';

// ─── Types ──────────────────────────────────────────────────────────────────

export type AreaCode = 'OUTDOOR' | 'MG' | 'SM' | 'SJ' | 'SC' | 'AB' | 'HM' | 'MT' | 'SB' | 'BBA' | 'GB';

export type ConnectionDirection =
  | 'straight'
  | 'left'
  | 'right'
  | 'slight-left'
  | 'slight-right'
  | 'u-turn'
  | 'stairs-up'
  | 'stairs-down'
  | 'ramp-up'
  | 'ramp-down'
  | 'enter-building'
  | 'exit-building'
  | 'unknown';

export type ConnectionType = 'forward' | 'backward' | 'junction' | 'transition';

export interface PanoramaConnection {
  id?: string;
  targetId: string;
  type: ConnectionType;
  direction?: ConnectionDirection;
  confirmed: boolean;
  heading?: number; // legacy heading
  worldBearing?: number; // Compass-relative world bearing (0=North, 90=East, 180=South, 270=West)
  targetYaw?: number; // Compass-relative or viewer yaw when arriving in target panorama
  initialViewerYaw?: number; // Explicit camera facing yaw upon arriving at target node
  pitch?: number;
  instruction?: string;
  distanceMeters?: number;
  walkingCost?: number; // distance + stairs/floor penalty
  bidirectional?: boolean;
  verified?: boolean;
  isEstimated?: boolean;
  verifiedStatus?: 'VERIFIED' | 'UNVERIFIED';

  // Navigation Direction Verification Metadata
  directionStatus?: 'VERIFIED' | 'UNVERIFIED' | 'AI_SUGGESTED' | 'NEEDS_REVIEW' | 'CONFLICT' | 'UNKNOWN';
  aiSuggestedDirection?: ConnectionDirection;
  aiConfidence?: number;
  aiEvidence?: {
    arrowAngleDeg?: number;
    relativeTurnDeg?: number;
    pitchDeg?: number;
    floorDiff?: number;
    areaTransition?: string | null;
    reason?: string;
  };
  directionVerifiedAt?: string;
  directionVerifiedBy?: string;
  previousVerifiedDirection?: ConnectionDirection;
  latestAISuggestion?: ConnectionDirection;
  unknownReason?: string;
}

export interface CampusPanoramaNode {
  id: string;
  image: string;
  imagePath: string;
  area: AreaCode;
  floor: string | null;
  filename: string;
  buildingId: string | null;
  floorId: string | null;
  position: { x: number; y: number } | null;
  northOffset: number | null; // Calibration offset between photo yaw 0 and world 0. Default null (uncalibrated).
  calibrationStatus: 'calibrated' | 'uncalibrated';
  captureTime: string;
  captureSequence: number;
  connections: PanoramaConnection[];
  isJunction: boolean;
  isBuildingEntrance: boolean;
  isFloorTransition: boolean;
  manualNumber?: string;
}

