/**
 * Detects if a tag text uses any official Christ College block short code
 * e.g. "AB 101", "AB-101", "SJ 204", "MG CS Lab", "MT Office", "SC Seminar Hall", "SB Room 12", "BPE Block"
 */
export function detectBlockFromTag(tagText: string): CollegeBlockMeta | null {
  if (!tagText) return null;
  const trimmed = tagText.trim();

  // Match prefix like "AB ", "AB-", "AB_", "AB101", "AB:", "BPE ", or exact "AB"
  const prefixMatch = trimmed.match(/^([A-Za-z]{2,3})(?:[\s\-:_0-9]|$)/);
  if (prefixMatch) {
    const code = prefixMatch[1].toUpperCase();
    if (CHRIST_COLLEGE_OFFICIAL_BLOCKS[code]) {
      return CHRIST_COLLEGE_OFFICIAL_BLOCKS[code];
    }
  }

  // Also check if any block short code or alias is isolated by word boundary
  for (const block of Object.values(CHRIST_COLLEGE_OFFICIAL_BLOCKS)) {
    const wordRegex = new RegExp(`\\b${block.shortCode}\\b`, 'i');
    if (wordRegex.test(trimmed)) {
      return block;
    }
    for (const alias of block.aliases) {
      const escaped = alias.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const aliasRegex = new RegExp(`\\b${escaped}\\b`, 'i');
      if (aliasRegex.test(trimmed)) {
        return block;
      }
    }
  }
  return null;
}

