// ─── Build node helper ──────────────────────────────────────────────────────

function makeNode(
  id: string,
  filename: string,
  folderName: string,
  area: AreaCode,
  floor: string | null = '0',
  connections: PanoramaConnection[] = [],
  isJunction: boolean = false,
  isBuildingEntrance: boolean = false,
  isFloorTransition: boolean = false,
  northOffset: number | null = null,
  calibrationStatus: 'calibrated' | 'uncalibrated' = 'uncalibrated',
  position: { x: number; y: number } | null = null,
  manualNumber?: string
): CampusPanoramaNode {
  const fileNumMatch = filename.match(/^0*(\d+)/);
  const derivedNum = fileNumMatch ? fileNumMatch[1] : String(parseInt(id.replace(/\D/g, ''), 10) || 0);

  return {
    id,
    image: filename,
    imagePath: `/assets/panoramas/${folderName}/${filename}`,
    area,
    floor,
    filename,
    buildingId: area === 'OUTDOOR' ? null : `building_${area.toLowerCase()}`,
    floorId: area === 'OUTDOOR' ? null : `floor_${area.toLowerCase()}_${floor || '0'}`,
    position,
    northOffset,
    calibrationStatus,
    captureTime: '12:00:00',
    captureSequence: parseInt(id.replace(/\D/g, ''), 10) || 0,
    connections,
    isJunction,
    isBuildingEntrance,
    isFloorTransition,
    manualNumber: manualNumber || derivedNum,
  };
}

