export const CAMPUS_GRAPH_MAP = new Map<string, CampusPanoramaNode>(
  CAMPUS_GRAPH.map((node) => [node.id, node])
);

export function getNodeById(id: string): CampusPanoramaNode | undefined {
  return CAMPUS_GRAPH_MAP.get(id);
}

export function getAllAvailablePanoramas(): { filename: string; imagePath: string; areaLabel: string; defaultNodeId: string }[] {
  return CAMPUS_GRAPH.map((n) => ({
    filename: n.filename,
    imagePath: n.imagePath,
    areaLabel: AREA_LABELS[n.area],
    defaultNodeId: n.id,
  }));
}

export function applyGraphOverrides(overrides: any) {
  if (!overrides) return;
  if (overrides.customPanoramas && typeof overrides.customPanoramas === 'object') {
    Object.entries(overrides.customPanoramas).forEach(([nodeId, cp]: [string, any]) => {
      if (!cp || !nodeId) return;
      const areaCode = (cp.area || 'OUTDOOR') as AreaCode;
      const floorStr =
        cp.floor === null || cp.floor === undefined
          ? null
          : Number(cp.floor) === 0
          ? 'Ground Floor'
          : `Floor ${cp.floor}`;
      const existing = CAMPUS_GRAPH_MAP.get(nodeId);
      if (existing) {
        existing.image = cp.image || existing.image;
        existing.imagePath = cp.imagePath || existing.imagePath;
        existing.filename = cp.filename || existing.filename;
        existing.area = areaCode;
        existing.floor = floorStr;
        if (cp.manualNumber) existing.manualNumber = String(cp.manualNumber);
      } else {
        const newNode: CampusPanoramaNode = {
          id: nodeId,
          image: cp.image || cp.filename || nodeId,
          imagePath: cp.imagePath || `/assets/panoramas/uploaded/${cp.filename || nodeId}`,
          area: areaCode,
          floor: floorStr,
          filename: cp.filename || cp.image || `${nodeId}.jpg`,
          buildingId: areaCode === 'OUTDOOR' ? null : areaCode,
          floorId: floorStr,
          position: null,
          northOffset: 0,
          calibrationStatus: 'calibrated',
          captureTime: cp.createdAt || new Date().toISOString(),
          captureSequence: CAMPUS_GRAPH.length + 1,
          connections: [],
          isJunction: false,
          isBuildingEntrance: false,
          isFloorTransition: false,
          manualNumber: cp.manualNumber ? String(cp.manualNumber) : String(CAMPUS_GRAPH.length + 1),
        };
        CAMPUS_GRAPH.push(newNode);
        CAMPUS_GRAPH_MAP.set(nodeId, newNode);
      }
    });
  }
  if (overrides.nodeMetadataOverrides && typeof overrides.nodeMetadataOverrides === 'object') {
    Object.entries(overrides.nodeMetadataOverrides).forEach(([nodeId, meta]: [string, any]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && meta) {
        if (meta.area) node.area = meta.area as AreaCode;
        if (meta.floor !== undefined && meta.floor !== null) {
          node.floor = Number(meta.floor) === 0 ? 'Ground Floor' : `Floor ${meta.floor}`;
        }
        if (meta.filename) node.filename = meta.filename;
      }
    });
  }
  if (overrides.customConnections) {
    Object.entries(overrides.customConnections).forEach(([nodeId, conns]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && Array.isArray(conns)) {
        node.connections = conns as PanoramaConnection[];
      }
    });
  }
  if (overrides.nodeImageOverrides) {
    Object.entries(overrides.nodeImageOverrides).forEach(([nodeId, imgData]: [string, any]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && imgData) {
        if (imgData.image) node.image = imgData.image;
        if (imgData.imagePath) node.imagePath = imgData.imagePath;
        if (imgData.filename) node.filename = imgData.filename;
      }
    });
  }
  if (overrides.nodeHeadingOverrides) {
    Object.entries(overrides.nodeHeadingOverrides).forEach(([nodeId, offset]: [string, any]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && typeof offset === 'number') {
        node.northOffset = offset;
        node.calibrationStatus = 'calibrated';
      }
    });
  }
  if (overrides.manualNumbers) {
    Object.entries(overrides.manualNumbers).forEach(([nodeId, num]: [string, any]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && typeof num === 'string') {
        node.manualNumber = num;
      }
    });
  }
  if (overrides.customPlaceTags) {
    setCustomPlaceTags(overrides.customPlaceTags);
  }
  if (overrides.nodeCameraAngles) {
    Object.entries(overrides.nodeCameraAngles).forEach(([nodeId, angle]: [string, any]) => {
      const node = CAMPUS_GRAPH_MAP.get(nodeId);
      if (node && typeof angle === 'number') {
        (node as any).defaultCameraYaw = angle;
      }
    });
  }
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('campnav:graph_updated'));
  }
}

import {
  BAKED_CUSTOM_PLACE_TAGS,
  BAKED_MANUAL_NUMBERS,
  BAKED_CUSTOM_CONNECTIONS,
  BAKED_NODE_CAMERA_ANGLES,
} from './defaultGraphOverrides';

let customPlaceTagsMap: Record<string, CustomPlaceTag[]> = { ...BAKED_CUSTOM_PLACE_TAGS };

// Apply baked manual numbers, custom connections, and camera angles immediately on module load
if (typeof window !== 'undefined') {
  Object.entries(BAKED_MANUAL_NUMBERS).forEach(([id, num]) => {
    const node = CAMPUS_GRAPH_MAP.get(id);
    if (node && typeof num === 'string') {
      node.manualNumber = num;
    }
  });

  Object.entries(BAKED_NODE_CAMERA_ANGLES).forEach(([id, angle]) => {
    const node = CAMPUS_GRAPH_MAP.get(id);
    if (node && typeof angle === 'number') {
      (node as any).defaultCameraYaw = angle;
    }
  });

  Object.entries(BAKED_CUSTOM_CONNECTIONS).forEach(([id, conns]) => {
    const node = CAMPUS_GRAPH_MAP.get(id);
    if (node && Array.isArray(conns) && conns.length > 0) {
      node.connections = conns;
    }
  });
}

export function getCustomPlaceTags(nodeId: string): CustomPlaceTag[] {
  return customPlaceTagsMap[nodeId] || [];
}

export function getAllCustomPlaceTags(): Record<string, CustomPlaceTag[]> {
  return customPlaceTagsMap;
}

export function setCustomPlaceTags(tagsMap: Record<string, CustomPlaceTag[]>) {
  customPlaceTagsMap = { ...BAKED_CUSTOM_PLACE_TAGS, ...(tagsMap || {}) };
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent('campnav:tags_updated'));
  }
}

export function getNodeManualNumber(nodeId: string): string {
  const node = CAMPUS_GRAPH_MAP.get(nodeId);
  return node?.manualNumber || nodeId;
}

export function getNodeDefaultCameraAngle(nodeId: string): number | undefined {
  const node = CAMPUS_GRAPH_MAP.get(nodeId);
  return (node as any)?.defaultCameraYaw;
}

export function resetGraphToDefault() {
  CAMPUS_GRAPH.forEach((node) => {
    CAMPUS_GRAPH_MAP.set(node.id, { ...node, connections: [...node.connections] });
  });
  setCustomPlaceTags(BAKED_CUSTOM_PLACE_TAGS);
}
